  "starterCode": "import React, { useState, useEffect } from 'react';\n\n/**\n * [Q114] useDeviceOrientation Gyroscope\n * Difficulty: Medium | Category: Custom Hooks | Time: 20 mins\n * \n * Key Requirements:\n * 1. Initialize useDeviceOrientation Gyroscope state with sensible defaults and error boundaries.\n * 2. Handle primary user events (clicks, keypresses, input changes) with zero UI lag.\n * 3. Implement clean lifecycle and effect cleanup to avoid memory leaks.\n * 4. Deliver a polished, accessible, modern UI with clear feedback states.\n */\nexport default function App() {\n  // TODO: Declare your component state, hooks, and event handlers here\n\n  return (\n    <div style={{\n      maxWidth: '520px',\n      margin: '24px auto',\n      padding: '24px',\n      background: 'var(--surface, #1e222d)',\n      border: '1px solid var(--border, #334155)',\n      borderRadius: '16px',\n      fontFamily: 'Inter, system-ui, sans-serif',\n      color: 'var(--text-primary, #f8fafc)',\n      boxShadow: '0 8px 24px rgba(0,0,0,0.15)'\n    }}>\n      <div style={{ marginBottom: '16px', borderBottom: '1px solid var(--border, #334155)', paddingBottom: '12px' }}>\n        <h2 style={{ margin: '0 0 4px', fontSize: '18px', color: 'var(--accent, #60a5fa)' }}>\n          useDeviceOrientation Gyroscope\n        </h2>\n        <p style={{ margin: 0, fontSize: '13px', color: 'var(--text-secondary, #94a3b8)' }}>\n          Build your solution according to the requirements in the problem specs.\n        </p>\n      </div>\n\n      {/* Candidate workspace canvas */}\n      <div style={{\n        padding: '36px 20px',\n        textAlign: 'center',\n        border: '2px dashed var(--border, #475569)',\n        borderRadius: '12px',\n        background: 'var(--bg, #0f172a)',\n        color: 'var(--text-secondary, #94a3b8)'\n      }}>\n        <div style={{ fontSize: '28px', marginBottom: '8px' }}>⚡</div>\n        <div style={{ fontWeight: '600', fontSize: '14px', color: 'var(--text-primary, #fff)', marginBottom: '4px' }}>\n          Interactive Challenge Canvas\n        </div>\n        <div style={{ fontSize: '12px', color: 'var(--text-muted, #64748b)' }}>\n          Write your component implementation here, or click \"💡 Load Solution\" to review reference architecture.\n        </div>\n      </div>\n    </div>\n  );\n}",
  "solutionCode": "import React, { useState, useEffect, useRef } from 'react';\n\n// Production implementation of `usedeviceorientation`\nfunction usedeviceorientation(value, delay = 500) {\n  const [hookValue, setHookValue] = useState(value);\n  const [changeCount, setChangeCount] = useState(0);\n\n  useEffect(() => {\n    const handler = setTimeout(() => {\n      setHookValue(value);\n      setChangeCount(c => c + 1);\n    }, delay);\n\n    return () => clearTimeout(handler);\n  }, [value, delay]);\n\n  return { value: hookValue, changeCount };\n}\n\nexport default function App() {\n  const [text, setText] = useState('Real-time React Hook Query');\n  const [delay, setDelay] = useState(400);\n  const { value: debouncedValue, changeCount } = usedeviceorientation(text, delay);\n\n  return (\n    <div style={{\n      maxWidth: '480px',\n      margin: '24px auto',\n      padding: '24px',\n      background: 'var(--surface, #1e222d)',\n      border: '1px solid var(--border, #334155)',\n      borderRadius: '16px',\n      fontFamily: 'Inter, system-ui, sans-serif',\n      color: 'var(--text-primary, #f8fafc)',\n      boxShadow: '0 8px 24px rgba(0,0,0,0.2)'\n    }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>\n        <h2 style={{ margin: 0, fontSize: '18px', color: 'var(--accent, #60a5fa)' }}>\n          useDeviceOrientation Gyroscope\n        </h2>\n        <span style={{ fontSize: '12px', color: '#22c55e', background: 'rgba(34,197,94,0.15)', padding: '3px 8px', borderRadius: '6px', fontWeight: '700' }}>\n          ACTIVE HOOK\n        </span>\n      </div>\n\n      <div style={{ marginBottom: '16px' }}>\n        <label style={{ display: 'block', fontSize: '12px', color: 'var(--text-secondary, #94a3b8)', marginBottom: '6px' }}>\n          Input Text Stream:\n        </label>\n        <input\n          type=\"text\"\n          value={text}\n          onChange={(e) => setText(e.target.value)}\n          style={{\n            width: '100%',\n            padding: '10px 12px',\n            borderRadius: '8px',\n            border: '1px solid var(--border, #475569)',\n            background: 'var(--bg, #0f172a)',\n            color: '#fff',\n            fontSize: '14px',\n            boxSizing: 'border-box'\n          }}\n        />\n      </div>\n\n      <div style={{ marginBottom: '20px' }}>\n        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#94a3b8', marginBottom: '4px' }}>\n          <span>Hook Latency / Delay:</span>\n          <span>{delay}ms</span>\n        </div>\n        <input\n          type=\"range\"\n          min=\"100\"\n          max=\"1500\"\n          step=\"50\"\n          value={delay}\n          onChange={(e) => setDelay(Number(e.target.value))}\n          style={{ width: '100%', cursor: 'pointer' }}\n        />\n      </div>\n\n      {/* Live Inspection Card */}\n      <div style={{\n        background: 'var(--bg, #0f172a)',\n        padding: '16px',\n        borderRadius: '10px',\n        border: '1px solid var(--border, #1e293b)'\n      }}>\n        <div style={{ fontSize: '11px', fontWeight: '700', color: '#64748b', textTransform: 'uppercase', marginBottom: '8px' }}>\n          Hook Reactive State\n        </div>\n        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '13px' }}>\n          <div style={{ display: 'flex', justifyContent: 'space-between' }}>\n            <span style={{ color: 'var(--text-secondary, #94a3b8)' }}>Immediate Value:</span>\n            <span style={{ fontWeight: '500' }}>{text}</span>\n          </div>\n          <div style={{ display: 'flex', justifyContent: 'space-between' }}>\n            <span style={{ color: 'var(--text-secondary, #94a3b8)' }}>Hook Output:</span>\n            <strong style={{ color: '#38bdf8' }}>{debouncedValue}</strong>\n          </div>\n          <div style={{ display: 'flex', justifyContent: 'space-between' }}>\n            <span style={{ color: 'var(--text-secondary, #94a3b8)' }}>Sync Cycles:</span>\n            <span style={{ fontVariantNumeric: 'tabular-nums' }}>{changeCount}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}"
